import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { FiArrowLeft, FiMapPin, FiCalendar } from 'react-icons/fi';
import eventService from '../services/eventService';
import galleryService from '../services/galleryService';
import stallService from '../services/stallService';
import StallForm from '../components/StallForm';
import '../styles/Pages.css';

const PastEventDetailsPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [event, setEvent] = useState(null);
  const [gallery, setGallery] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submittingStall, setSubmittingStall] = useState(false);
  const [stallMessage, setStallMessage] = useState(null);

  useEffect(() => {
    fetchEventDetails();
  }, [id]);

  const fetchEventDetails = async () => {
    setLoading(true);
    try {
      // Fetch event details
      const eventData = await eventService.getEventById(id);
      setEvent(eventData);

      // Fetch gallery for this event
      try {
        const galleryData = await galleryService.getGalleryByEvent(id);
        setGallery(galleryData || []);
      } catch (error) {
        console.log('No gallery found for this event');
        setGallery([]);
      }
    } catch (error) {
      console.error('Error fetching event details:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="past-event-details-page">
        <div className="loading">Loading event details...</div>
      </div>
    );
  }

  if (!event) {
    return (
      <div className="past-event-details-page">
        <div className="error-message">Event not found</div>
      </div>
    );
  }

  return (
    <div className="past-event-details-page">
      {/* Header */}
      <div className="past-event-header">
        <button 
          className="back-button"
          onClick={() => navigate('/past-events')}
        >
          <FiArrowLeft size={20} /> Back to Past Events
        </button>
      </div>

      {/* Event Banner */}
      {event.thumbnail && (
        <div className="past-event-banner">
          <img 
            src={event.thumbnail} 
            alt={event.title}
            className="past-event-banner-image"
          />
        </div>
      )}

      {/* Event Details Container */}
      <div className="past-event-details-container">
        {/* Main Info */}
        <div className="past-event-main">
          <h1>{event.title}</h1>
          <p className="event-description">{event.description}</p>

          {/* Key Info */}
          <div className="event-key-info">
            <div className="info-card">
              <FiCalendar size={20} />
              <div>
                <h4>Event Duration</h4>
                <p>{new Date(event.startDate).toLocaleDateString('en-US', { 
                  year: 'numeric', 
                  month: 'long', 
                  day: 'numeric' 
                })}</p>
                <p className="small-text">to {new Date(event.endDate).toLocaleDateString('en-US', { 
                  year: 'numeric', 
                  month: 'long', 
                  day: 'numeric' 
                })}</p>
              </div>
            </div>

            <div className="info-card">
              <FiMapPin size={20} />
              <div>
                <h4>Venue</h4>
                <p>{event.venue || 'Location not specified'}</p>
              </div>
            </div>
          </div>

          {/* Details Grid */}
          <div className="details-grid">
            <div className="detail-item">
              <h4>Category</h4>
              <p>{event.category || 'Not specified'}</p>
            </div>
            <div className="detail-item">
              <h4>Status</h4>
              <span className={`status-badge ${event.status}`}>{event.status}</span>
            </div>
            <div className="detail-item">
              <h4>Organizer</h4>
              <p>{event.organizer?.name || 'Unknown'}</p>
            </div>
            <div className="detail-item">
              <h4>Attendees</h4>
              <p>{event.attendees?.length || 0} people attended</p>
            </div>
          </div>
        </div>

        {/* Gallery Section */}
        {gallery.length > 0 && (
          <div className="past-event-gallery-section">
            <h2>Event Memories</h2>
            <div className="gallery-grid">
              {gallery.map((photo) => (
                <div key={photo._id} className="gallery-item">
                  <img 
                    src={photo.photoUrl} 
                    alt={photo.caption || 'Event photo'}
                    className="gallery-image"
                  />
                  {photo.caption && (
                    <div className="photo-caption">{photo.caption}</div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {gallery.length === 0 && (
          <div className="no-gallery">
            <p>No photos uploaded for this event yet</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PastEventDetailsPage;
